with flattened_attrs as (select id, plan, currency, tier_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, array_min(tier_prices) as lowest_price from price_tiers where plan = 'basic') select id, currency, lag(lowest_price, 1) over w_hist as prev_lowest_price, avg(lowest_price) over (partition by currency, plan order by lowest_price, id rows between 2 preceding and current row) as lowest_price_avg_2, row_number() over (partition by plan, currency order by lowest_price, id) as seq_no, last_value(lowest_price, true) over w_ordered as last_known_lowest_price, percent_rank() over (partition by currency order by lowest_price nulls last) as lowest_price_percent_rank from flattened_attrs window w_hist as (partition by plan order by lowest_price, id), w_ordered as (partition by plan, currency order by lowest_price, id rows between unbounded preceding and current row);
